CREATE TABLE promotion_pages(slug text PRIMARY KEY,config jsonb NOT NULL);
CREATE TABLE promotion_sections(slug text PRIMARY KEY,page_slug text NOT NULL REFERENCES promotion_pages(slug),position integer NOT NULL,config jsonb NOT NULL);
WITH added AS (INSERT INTO offers(product_id,seller_id,region_id,price_cents,old_price_cents) SELECT p.id,s.id,r.id,211,6350 FROM products p CROSS JOIN sellers s CROSS JOIN regions r WHERE p.slug='cheap-suicide-squad-kill-the-justice-league-pc-steam-key-global' AND s.name='GameNest' AND r.slug='global' RETURNING id) INSERT INTO key_inventory(offer_id,key_value) SELECT id,'TEST-CHEAP-'||id||'-'||n FROM added CROSS JOIN generate_series(1,15)n;
